window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[161]={"id":"161","numero":161,"titre":"Infections urinaires de l'adulte et de l'enfant","objectifs":[{"id":"161-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition des différents types d'infections des voies urinaires simples ou à risque de complication et leur fréquence respective","contenu":"<p>Une <span class=\"kw-def\">infection urinaire (IU)</span> associe la <span class=\"kw-bio\">multiplication bactérienne</span> dans l'arbre urinaire à des <span class=\"kw-clinique\">signes cliniques</span>. On la classe selon le <span class=\"kw-def\">terrain</span> en trois catégories qui conditionnent toute la prise en charge.</p>\n      <table >\n        <thead><tr><th>Type</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>IU simple</strong></span></td>\n            <td><span class=\"kw-clinique\">Femme sans facteur de risque de complication</span> ; souvent due à des souches <span class=\"kw-etio\">uropathogènes virulentes</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>IU à risque de complication</strong></span></td>\n            <td>Présence d'<strong><span class=\"kw-chiffre\">≥ 1</span> facteur</strong> favorisant un échec ou une forme grave :\n              <ul>\n                <li><span class=\"kw-etio\">Anomalie organique/fonctionnelle</span> de l'arbre urinaire (<span class=\"kw-clinique\">résidu post-mictionnel</span>, RVU, lithiase, tumeur, <span class=\"kw-clinique\">syndrome de la</span> jonction, <span class=\"kw-etio\">polykystose</span>, ATCD de <span class=\"kw-ttt\">chirurgie</span> urologique)</li>\n                <li><span class=\"kw-etio\">Sexe masculin</span></li>\n                <li>Âge <span class=\"kw-chiffre\">&gt; 75 ans</span>, ou <span class=\"kw-chiffre\">&gt; 65 ans</span> avec <span class=\"kw-chiffre\">≥ 3</span> <span class=\"kw-def\">critères de</span> fragilité de Fried</li>\n                <li><span class=\"kw-etio\">Grossesse</span></li>\n                <li><span class=\"kw-etio\">IRC sévère</span> (<span class=\"kw-bio\">clairance</span> <span class=\"kw-chiffre\">&lt; 30 mL/min</span>)</li>\n                <li><span class=\"kw-etio\">Immunodépression grave</span> (<span class=\"kw-etio\">VIH</span> <span class=\"kw-chiffre\">CD4</span> &lt; 200, transplanté, <span class=\"kw-ttt\">immunosuppresseurs</span>, chimiothérapie)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>IU grave</strong></span></td>\n            <td>Concerne <strong>uniquement <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">PNA</span> et les <span class=\"kw-clinique\">IU masculines</span></strong> (<span class=\"kw-alerte\">la cystite n'est jamais grave</span>) associées à : <span class=\"kw-alerte\">sepsis</span>, <span class=\"kw-alerte\">choc septique</span>, ou <span class=\"kw-alerte\">indication de geste urologique</span> (<span class=\"kw-ttt\">drainage</span> chirurgical, radiologie interventionnelle — hors sondage simple). Un <span class=\"kw-etio\">obstacle</span> est souvent retrouvé.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>⚠️ Piège des étoiles</strong> — le <span class=\"kw-clinique\">diabète</span> (même insulino-requérant) <strong>n'est PLUS un <span class=\"kw-def\">facteur de risque</span> de complication</strong> : c'est seulement un <span class=\"kw-etio\">facteur favorisant</span>.\n      </div>\n      <p><strong>Fréquence respective</strong></p>\n      <ul>\n        <li>IU communautaires = <strong>2ᵉ site</strong> d'infection <span class=\"kw-etio\">bactérienne</span> (après l'arbre bronchopulmonaire).</li>\n        <li>IU parenchymateuses (PNA, <span class=\"kw-clinique\">prostatite</span>) = <strong>3ᵉ cause</strong> d'état septique grave.</li>\n        <li>Nette <span class=\"kw-clinique\">prédominance féminine</span> : <span class=\"kw-chiffre\">⅓</span> des femmes feront une IU ; chez l'homme, fréquence qui augmente <span class=\"kw-chiffre\">après 50 ans</span> (pathologie prostatique).</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 50 — Pathologie génito-scrotale chez le garçon et chez l'homme · 28 — Principales complications de la <span class=\"kw-ci\">grossesse</span></em></p>","frequence":2},{"id":"161-2","rang":"A","rubrique":"Étiologies","titre":"Connaître les principaux agents pathogènes à l'origine des infections urinaires et les principaux mécanismes de résistance aux antibiotiques","contenu":"<p><span class=\"kw-clinique\">Les</span> IU sont le plus souvent <span class=\"kw-def\">monomicrobiennes</span> et dues à des <span class=\"kw-etio\">entérobactéries d'origine digestive (BGN)</span>. À connaître par ordre de fréquence :</p>\n      <table >\n        <thead><tr><th>Germe</th><th>À retenir</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>E. coli</strong></span> <span class=\"kw-chiffre\">(50-90 %)</span></td>\n            <td>Entérobactérie de référence, spectre que tout ATB probabiliste <strong>doit couvrir</strong>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Proteus mirabilis</span> <span class=\"kw-chiffre\">(10 %)</span></td>\n            <td>Bactérie à <span class=\"kw-bio\">uréase</span> → favorise <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">lithiases à struvite</span> (phospho-ammoniaco-magnésien).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">S. saprophyticus</span> <span class=\"kw-chiffre\">(3-7 %)</span></td>\n            <td>🚩 <span class=\"kw-clinique\">Cystite de la femme jeune après rapport sexuel</span> ; évoqué si <span class=\"kw-bio\">BU avec nitrites négatifs</span> (cocci Gram +).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Entérocoques</span></td>\n            <td>Résistance <strong>naturelle</strong> à toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-ci\">céphalosporines</span> et aux <span class=\"kw-ci\">quinolones</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Klebsiella, Pseudomonas, Serratia</span></td>\n            <td>🏥 Souvent <span class=\"kw-alerte\">résistantes</span> ; contexte nosocomial (sonde à demeure, <span class=\"kw-etio\">diabète</span>, immunodépression).</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>S'y ajoutent le <span class=\"kw-etio\">Staphylocoque doré</span> (<span class=\"kw-clinique\">septicémie</span> 🏥), la <span class=\"kw-etio\">tuberculose urinaire</span> (exceptionnelle, <span class=\"kw-alerte\">leucocyturie aseptique</span> 🚩) et <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">Candida</span> (sonde, <span class=\"kw-etio\">diabète</span>, ATB large spectre — candidurie souvent non pathogène).</p>\n      <p><strong>Mécanismes de résistance d'<span class=\"kw-etio\">E. coli</span> (selon <span class=\"kw-def\">prévalence</span>)</strong></p>\n      <ul>\n        <li><span class=\"kw-chiffre\">&lt; 5 %</span> : <span class=\"kw-ttt\">fosfomycine-trométamol</span>, <span class=\"kw-ttt\">nitrofurantoïne</span>, <span class=\"kw-ttt\">aminosides</span>.</li>\n        <li><span class=\"kw-chiffre\">5-20 %</span> : C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span> (<span class=\"kw-bio\">BLSE</span>), <span class=\"kw-ttt\">fluoroquinolones</span>, pivmécillinam.</li>\n        <li><span class=\"kw-alerte\">&gt; 20 %</span> : <span class=\"kw-ci\">amoxicilline</span> (pénicillinase), <span class=\"kw-ci\">amoxicilline-ac. clavulanique</span>, <span class=\"kw-ci\">cotrimoxazole/triméthoprime</span> → <strong>jamais en probabiliste</strong>.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-bio\">EBLSE</span></strong> — entérobactérie productrice de <span class=\"kw-bio\">β-lactamase à spectre élargi</span> (résistance aux C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span>). Le risque d'EBLSE n'est pris en compte que pour <strong>l'ATB probabiliste des IU graves</strong>. Molécules actives (par efficacité) : <span class=\"kw-ttt\">carbapénèmes</span> &gt; <span class=\"kw-ttt\">fosfomycine</span> &gt; <span class=\"kw-ttt\">amikacine</span> &gt; céfoxitine &gt; <span class=\"kw-ttt\">pipéracilline-tazobactam</span>.\n      </div>","frequence":4},{"id":"161-3","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens complémentaires de première intention en fonction du type d'infection urinaire","contenu":"<p>Le bilan de 1ʳᵉ intention se hiérarchise selon le <span class=\"kw-def\">type d'IU</span> : la clinique prime toujours, l'examen confirme.</p>\n      <table >\n        <thead><tr><th>Situation</th><th>1ʳᵉ intention</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Cystite aiguë simple</span></td>\n            <td><span class=\"kw-bio\">BU seule</span> ; <strong>pas d'<span class=\"kw-bio\">ECBU</span></strong>, pas d'imagerie.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Cystite à risque de complication / récidivante</span></td>\n            <td><span class=\"kw-bio\">BU + ECBU</span> systématique.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">PNA</span></td>\n            <td><span class=\"kw-bio\">BU + ECBU</span> ; <span class=\"kw-imagerie\">échographie rénale</span> si <span class=\"kw-alerte\">PNA hyperalgique</span> (&lt;<span class=\"kw-chiffre\"> 24 h</span>) ou <span class=\"kw-clinique\">évolution</span> défavorable à<span class=\"kw-chiffre\"> 72 h</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">IU masculine</span></td>\n            <td><span class=\"kw-bio\">BU + ECBU</span> (seuil 10³ UFC/mL) ; <span class=\"kw-imagerie\">échographie par voie sus-pubienne</span> <span class=\"kw-chiffre\">≤ 24 h</span> ; <span class=\"kw-bio\">hémocultures si fièvre</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Femme enceinte</span></td>\n            <td><span class=\"kw-bio\">ECBU mensuel</span> systématique à partir du <span class=\"kw-chiffre\">4ᵉ mois</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir</strong> — l'<span class=\"kw-bio\">ECBU</span> est aussi systématique avant toute <span class=\"kw-clinique\">chirurgie programmée des voies urinaires</span>. Pas d'<span class=\"kw-bio\">ECBU</span> systématique sur simple matériel endo-urinaire ni en contrôle si l'<span class=\"kw-clinique\">évolution</span> est favorable.\n      </div>","frequence":3},{"id":"161-4","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens complémentaires de deuxième intention en fonction du type d'infection urinaire","contenu":"<p><span class=\"kw-clinique\">Les</span> examens de 2ᵉ intention sont déclenchés par une <span class=\"kw-alerte\">forme grave</span>, une <span class=\"kw-alerte\">évolution défavorable</span> ou un <span class=\"kw-def\">terrain</span> particulier.</p>\n      <ul>\n        <li><span class=\"kw-imagerie\"><strong>Uroscanner</strong></span> (<span class=\"kw-imagerie\">TDM</span> injectée à temps tardif) : <span class=\"kw-clinique\">PNA à risque de complication</span> ou <span class=\"kw-alerte\">PNA grave</span>, PNA d'<span class=\"kw-clinique\">évolution</span> défavorable à<span class=\"kw-chiffre\"> 72 h</span>, IU masculine grave. Recherche : <span class=\"kw-imagerie\">obstacle avec dilatation pyélocalicielle</span>, <span class=\"kw-imagerie\">foyer de néphrite</span> (hypodensité triangulaire à base externe, <strong>pathognomonique</strong>), <span class=\"kw-alerte\">abcès rénal</span>, <span class=\"kw-clinique\">phlegmon</span> périnéphrétique.</li>\n        <li><span class=\"kw-imagerie\">Échographie</span> en 2ᵉ intention : si <span class=\"kw-ci\">contre-indication à l'uroscanner</span>.</li>\n        <li>IU masculine d'<span class=\"kw-clinique\">évolution</span> défavorable : <span class=\"kw-imagerie\">IRM de prostate</span> ou <span class=\"kw-imagerie\">échographie endorectale</span> (recherche d'<span class=\"kw-clinique\">abcès</span>).</li>\n        <li>Cystites récidivantes : <span class=\"kw-bio\">débitmétrie</span>, <span class=\"kw-bio\">mesure du résidu post-mictionnel</span>, voire cystoscopie / cystographie.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège</strong> — aucun examen du <span class=\"kw-clinique\">haut appareil</span> (<span class=\"kw-imagerie\">TDM</span>/écho) n'est nécessaire pour une <span class=\"kw-clinique\">cystite récidivante simple</span> de la femme non ménopausée à examen clinique normal.\n      </div>","frequence":1},{"id":"161-5","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les principes de réalisation de la bandelette urinaire et son interprétation","contenu":"<p>La <span class=\"kw-def\">bandelette urinaire (BU)</span> détecte deux marqueurs ; elle <strong>ne fait que confirmer la clinique</strong>, qui prime toujours.</p>\n      <p><strong>Réalisation</strong></p>\n      <ul>\n        <li>Récipient <span class=\"kw-clinique\">propre mais non stérile</span>, bandelettes <strong>non périmées</strong>.</li>\n        <li><span class=\"kw-alerte\">Pas de toilette préalable</span> ❌ ; urines fraîches du <span class=\"kw-clinique\">2ᵉ jet / milieu de jet</span>.</li>\n        <li>Lecture après <span class=\"kw-chiffre\">~2 minutes</span>.</li>\n      </ul>\n      <table >\n        <thead><tr><th>Marqueur</th><th>Principe · seuil · faux résultats</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Leucocytes</strong></span></td>\n            <td><strong>Principe :</strong> <span class=\"kw-bio\">leucocyte-estérase</span> des PNN ; seuil <span class=\"kw-chiffre\">10⁴/mL</span><br>\n              <strong>Faux négatifs :</strong> immunodépression, neutropénie, IU masculine<br>\n              <strong>Faux positifs :</strong> <span class=\"kw-alerte\">matériel endo-urinaire</span> (sonde) systématiquement</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Nitrites</strong></span></td>\n            <td><strong>Principe :</strong> nitrate-réductase des <span class=\"kw-etio\">entérobactéries</span> ; seuil <span class=\"kw-chiffre\">10⁵ UFC/mL</span><br>\n              <strong>Faux négatifs :</strong> faible bactériurie, <span class=\"kw-bio\">pH</span> acide, urines diluées, <span class=\"kw-etio\">germes sans nitrate-réductase</span> (<span class=\"kw-etio\">Pseudomonas</span>, Acinetobacter, cocci Gram + : staph, <span class=\"kw-etio\">entérocoque</span>, streptocoque)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>Interprétation selon le sexe (clé EDN)</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">Femme</span> : excellente <span class=\"kw-bio\">VPN</span> → une <span class=\"kw-bio\">BU</span> négative (ni <span class=\"kw-bio\">leucocytes</span> ni <span class=\"kw-bio\">nitrites</span>, hors immunodépression) doit faire <span class=\"kw-alerte\">chercher un autre diagnostic</span>.</li>\n          <li><span class=\"kw-clinique\">Homme</span> : bonne <span class=\"kw-bio\">VPP</span> si <span class=\"kw-bio\">leucocytes</span> <strong>et/ou</strong> <span class=\"kw-bio\">nitrites</span>, mais une <span class=\"kw-alerte\">BU négative n'élimine PAS</span> une IU masculine.</li>\n        </ul>\n      </div>","frequence":3},{"id":"161-6","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les principes de réalisation et l'interprétation de l'examen cytobactériologique des urines (ECBU)","contenu":"<p>L'<span class=\"kw-def\">ECBU</span> couple <span class=\"kw-bio\">cytologie</span> (<span class=\"kw-bio\">leucocyturie</span>, hématies), <span class=\"kw-bio\">examen direct</span> (Gram), <span class=\"kw-bio\">culture</span> et <span class=\"kw-bio\">antibiogramme</span>. Son principal écueil est la <span class=\"kw-alerte\">contamination du prélèvement</span> (cellules épithéliales à l'examen direct).</p>\n      <p><strong>Réalisation</strong></p>\n      <ul>\n        <li><strong>Avant toute ATB</strong>, si possible <span class=\"kw-chiffre\">&gt; 4 h</span> après la miction précédente.</li>\n        <li>Hygiène des mains, <span class=\"kw-clinique\">toilette urétrale/vulvaire</span>, recueil du <span class=\"kw-clinique\">milieu de jet</span> (laisser couler ~<span class=\"kw-chiffre\">20 mL</span>).</li>\n        <li>Patient sondé : prélèvement par <span class=\"kw-clinique\">ponction de l'opercule</span> (jamais dans le sac collecteur ❌).</li>\n        <li>Transport rapide : <span class=\"kw-chiffre\">&lt; 2 h</span> à T° ambiante, <span class=\"kw-chiffre\">&lt; 24 h</span> à<span class=\"kw-chiffre\"> 4 °C</span>.</li>\n      </ul>\n      <p><strong>Seuils d'interprétation</strong></p>\n      <ul>\n        <li><span class=\"kw-bio\">Leucocyturie significative</span> : <span class=\"kw-chiffre\">&gt; 10⁴/mL</span> (&gt; 10 éléments/mm³).</li>\n        <li>Bactériurie : <span class=\"kw-chiffre\">10³ UFC/mL</span> (homme, ou <span class=\"kw-etio\">E. coli</span>/S. saprophyticus chez la femme) ; <span class=\"kw-chiffre\">10⁴</span> (autres germes chez la femme) ; <span class=\"kw-chiffre\">10⁵</span> (sonde, <span class=\"kw-clinique\">bactériurie asymptomatique</span> gravidique).</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-bio\">Leucocyturie</span> aseptique</strong> (<span class=\"kw-bio\">leucocyturie</span> sans bactérie) — y penser : <span class=\"kw-alerte\">infection décapitée par ATB</span>, <span class=\"kw-etio\">tuberculose uro-génitale</span>, <span class=\"kw-etio\">Chlamydia</span>, tumeur urothéliale, <span class=\"kw-clinique\">cystite</span> interstitielle, période péri-menstruelle.\n      </div>\n      <p>Le diagnostic d'IU = <span class=\"kw-clinique\">patient symptomatique</span> + <span class=\"kw-bio\">leucocyturie</span> + <span class=\"kw-bio\">bactériurie significative</span>. En cas de discordance, <strong>le tableau clinique prime</strong>.</p>","frequence":2},{"id":"161-7","rang":"A","rubrique":"Définition","titre":"Connaître la définition d'une colonisation urinaire","contenu":"<p>La <span class=\"kw-def\">colonisation urinaire</span> (= <span class=\"kw-clinique\">bactériurie asymptomatique</span>) est une situation de <span class=\"kw-def\">commensalisme</span> : <strong>ce n'est PAS une <span class=\"kw-clinique\">infection urinaire</span></strong>.</p>\n      <ul>\n        <li><strong>Signes négatifs :</strong> <span class=\"kw-clinique\">pas de signe fonctionnel urinaire</span>, <span class=\"kw-clinique\">pas de fièvre</span>, pas de <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">inflammatoire</span></span> — quel que soit le niveau de <span class=\"kw-bio\">leucocyturie</span>.</li>\n        <li><strong>Pas de seuil de bactériurie</strong> ❌ — sauf chez la <span class=\"kw-etio\">femme enceinte</span> : <span class=\"kw-chiffre\">10⁵ UFC/mL</span> sur <span class=\"kw-chiffre\">2 ECBU</span> consécutifs.</li>\n        <li><strong>FR :</strong> <span class=\"kw-clinique\">sujet âgé</span>, <span class=\"kw-clinique\">sonde à demeure</span> (<span class=\"kw-chiffre\">100 %</span> colonisés à<span class=\"kw-chiffre\"> 1 mois</span>), <span class=\"kw-etio\">diabète</span>, <span class=\"kw-clinique\">incontinence</span>, <span class=\"kw-etio\">HBP</span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong>On ne traite QUE 2 situations</strong> (= indications de <span class=\"kw-def\">dépistage</span>) :\n        <ul>\n          <li><span class=\"kw-etio\">Femme enceinte</span></li>\n          <li>Avant un <span class=\"kw-clinique\">geste invasif sur les voies urinaires</span></li>\n        </ul>\n        Sinon, traiter est <strong>délétère</strong> : <span class=\"kw-alerte\">sélection de résistances</span>, perte de l'effet protecteur contre <span class=\"kw-clinique\">les</span> souches invasives, sans bénéfice sur la <span class=\"kw-bio\">fonction rénale</span>.\n      </div>","frequence":1},{"id":"161-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les critères diagnostiques des cystites aiguës (simples, à risque de complication)","contenu":"<p>La <span class=\"kw-def\">cystite</span> est une <span class=\"kw-def\">réponse inflammatoire</span> de la muqueuse vésicale, par définition <strong>chez la femme uniquement</strong> (chez l'homme = IU masculine). C'est un diagnostic <strong>clinique</strong>.</p>\n      <p><strong>Tableau (SBAU de remplissage, par fréquence)</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Brûlures mictionnelles</span> (<span class=\"kw-chiffre\">96 %</span>), <span class=\"kw-clinique\">pollakiurie</span> (<span class=\"kw-chiffre\">78 %</span>), <span class=\"kw-clinique\">urgenturies</span> (<span class=\"kw-chiffre\">63 %</span>).</li>\n        <li><span class=\"kw-clinique\">Douleurs sus-pubiennes</span> de fin de miction (<span class=\"kw-chiffre\">47 %</span>), <span class=\"kw-clinique\">hématurie</span> (<span class=\"kw-chiffre\">16 %</span>, non grave).</li>\n        <li><strong>Début aigu</strong> : une symptomatologie traînant depuis plusieurs semaines n'est quasi jamais infectieuse.</li>\n        <li><span class=\"kw-alerte\">Absence de syndrome infectieux</span> (ni <span class=\"kw-clinique\">fièvre</span>, ni <span class=\"kw-clinique\">douleur lombaire</span>) — sinon évoquer une PNA.</li>\n      </ul>\n      <table >\n        <thead><tr><th></th><th><span class=\"kw-clinique\">Cystite</span> simple</th><th>Cystite à risque de complication</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td>Femme <span class=\"kw-clinique\">sans FR</span></td>\n            <td><span class=\"kw-etio\">≥ 1 FR de complication</span> (uropathie, &gt;<span class=\"kw-chiffre\"> 75 ans</span>, IRC, immunodépression, <span class=\"kw-ci\">grossesse</span>…)</td>\n          </tr>\n          <tr>\n            <td><strong>Paraclinique</strong></td>\n            <td><span class=\"kw-bio\">BU seule</span> (bonne VPN)</td>\n            <td><span class=\"kw-bio\">ECBU systématique</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À savoir</strong> — <span class=\"kw-clinique\">évolution</span> spontanément favorable dans <span class=\"kw-chiffre\">87 %</span> des cas à<span class=\"kw-chiffre\"> 10 jours</span> ; le risque de PNA ascendante est <span class=\"kw-chiffre\">minime</span> (l'objectif de l'ATB est le confort, pas la prévention de la PNA).\n      </div>","frequence":4},{"id":"161-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les critères diagnostiques des pyélonéphrites aiguës (cliniques, biologiques, radiologiques) avec ou sans signe de gravité (algorithme)","contenu":"<p>La <span class=\"kw-def\">PNA</span> est une inflammation du <span class=\"kw-clinique\">rein et de sa voie excrétrice</span>. Tableau associant <strong><span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">infectieux</span></span> + douleur lombaire</strong>.</p>\n      <p><strong>Clinique</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Syndrome infectieux</span> (<span class=\"kw-clinique\">fièvre</span>, frissons) <strong>systématique</strong> ; prodromes de <span class=\"kw-clinique\">cystite</span> inconstants (<span class=\"kw-chiffre\">50 %</span>).</li>\n        <li><span class=\"kw-clinique\">Douleur lombaire unilatérale</span>, provoquée par la <span class=\"kw-clinique\">percussion de la fosse lombaire</span>, irradiant vers <span class=\"kw-clinique\">les</span> OGE.</li>\n        <li><span class=\"kw-clinique\">Signes digestifs</span> par <span class=\"kw-clinique\">iléus</span> réflexe (<span class=\"kw-clinique\">vomissements</span>, diarrhée, météorisme) parfois au 1ᵉʳ plan.</li>\n      </ul>\n      <p><strong>Biologie · imagerie</strong></p>\n      <ul>\n        <li><span class=\"kw-bio\">BU + ECBU</span> ; <span class=\"kw-bio\">CRP, créatinine, urée</span> si forme à risque ; <span class=\"kw-bio\">hémocultures</span> si grave (positives <span class=\"kw-chiffre\">25 %</span>).</li>\n        <li><span class=\"kw-imagerie\">Échographie</span> si hyperalgique (&lt;<span class=\"kw-chiffre\"> 24 h</span>) ; <span class=\"kw-imagerie\">uroscanner &lt; 24 h</span> si à risque de complication ou grave → recherche d'<span class=\"kw-imagerie\">obstacle</span> et de <span class=\"kw-alerte\">foyer de néphrite</span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong>Algorithme — démarche en 4 questions</strong>\n        <ol>\n          <li><strong>Sexe ?</strong> Homme → <span class=\"kw-clinique\">IU masculine</span>.</li>\n          <li><strong><span class=\"kw-ci\">Grossesse</span> ?</strong> <span class=\"kw-bio\">β-hCG</span> systématique → <span class=\"kw-clinique\">PNA gravidique</span>.</li>\n          <li><strong>Gravité ?</strong> <span class=\"kw-alerte\">PNA grave</span> si <span class=\"kw-alerte\">sepsis</span> / <span class=\"kw-alerte\">choc</span> / geste urologique (<span class=\"kw-chiffre\">qSOFA</span> <span class=\"kw-chiffre\">≥ 2</span>).</li>\n          <li><strong>FR de complication ?</strong> Présents → <span class=\"kw-clinique\">PNA à risque</span> ; sinon → <span class=\"kw-clinique\">PNA simple</span>.</li>\n        </ol>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 157 — <span class=\"kw-clinique\">Sepsis</span> · Bactériémie · Fongémie · 158 — Sepsis et <span class=\"kw-alerte\">choc septique</span> de l'enfant et de l'adulte</em></p>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/acute-pyelonephritis-1","label":"Radiopaedia : Acute pyelonephritis"}]},{"id":"161-10","rang":"A","rubrique":"Prise en charge","titre":"Connaître le traitement des cystites aiguës simples dont suivi et prévention des récidives","contenu":"<p>Objectif du traitement = <strong>soulager <span class=\"kw-clinique\">les</span> symptômes</strong> (pas prévenir une PNA). Moyen mnémotechnique : « <strong>fa-trop-pi-sser</strong> » = <span class=\"kw-ttt\">Fosfomycine</span> → <span class=\"kw-ttt\">Pivmécillinam</span> → <span class=\"kw-ttt\">Nitrofurantoïne</span>.</p>\n      <p><strong><span class=\"kw-ttt\">Antibiothérapie</span> (ordre de choix)</strong></p>\n      <ol>\n        <li><span class=\"kw-ttt\"><strong>Fosfomycine-trométamol</strong></span> en <span class=\"kw-chiffre\">dose unique</span> (meilleure observance, résistance rare) — sauf si <span class=\"kw-bio\">BU</span> à <span class=\"kw-bio\">nitrites</span> négatifs évoquant <span class=\"kw-etio\">S. saprophyticus</span>.</li>\n        <li><span class=\"kw-ttt\">Pivmécillinam</span> pendant <span class=\"kw-chiffre\">3-5 jours</span>.</li>\n        <li><span class=\"kw-ttt\">Nitrofurantoïne</span> <span class=\"kw-chiffre\">5 jours</span> (3ᵉ intention, en dernier recours — <span class=\"kw-ci\">toxicité hépatique/pulmonaire</span> rare mais grave, jamais au long cours).</li>\n      </ol>\n      <div class=\"callout callout-info\">\n        <strong>Mesures d'hygiène (toujours)</strong> — hydratation <span class=\"kw-chiffre\">&gt; 1,5 L/j</span>, mictions fréquentes (toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">4-6 h</span>), uriner après les rapports, régulariser le transit.\n      </div>\n      <p><strong><span class=\"kw-def\">Suivi</span></strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Évolution</span> favorable en <span class=\"kw-chiffre\">2-3 jours</span> → aucun contrôle.</li>\n        <li><span class=\"kw-bio\">ECBU de contrôle</span> seulement si <span class=\"kw-alerte\">échec à 72 h</span> ou <span class=\"kw-alerte\">récidive &lt; 2 semaines</span>.</li>\n        <li>Récidive dans <span class=\"kw-chiffre\">20-30 %</span> des cas.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span class=\"kw-def\">surveillance</span> des anti-<span class=\"kw-etio\">infectieux</span> chez l'adulte et l'enfant</em></p>","frequence":7},{"id":"161-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités du traitement des pyélonéphrites aiguës simples","contenu":"<p>La <span class=\"kw-def\">PNA simple</span> (femme, sans FR, sans gravité) se traite en <strong><span class=\"kw-clinique\">ambulatoire</span></strong>, par voie orale dès que possible.</p>\n      <p><strong>ATB probabiliste</strong> (débutée après l'<span class=\"kw-bio\">ECBU</span>)</p>\n      <ol>\n        <li><span class=\"kw-ttt\">Fluoroquinolone per os</span> (si pas de quinolone dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois</span>).</li>\n        <li><span class=\"kw-ttt\">C3G parentérale</span> (<span class=\"kw-ttt\">céfotaxime</span> / <span class=\"kw-ttt\">ceftriaxone</span>) si quinolone récente.</li>\n        <li><span class=\"kw-ttt\">Aminoside</span> ou <span class=\"kw-ttt\">aztréonam</span> si <span class=\"kw-ci\">allergie</span>.</li>\n      </ol>\n      <p><strong>ATB de relais adaptée à l'<span class=\"kw-bio\">antibiogramme</span></strong> (même ordre pour toutes <span class=\"kw-clinique\">les</span> PNA) : <span class=\"kw-ttt\">amoxicilline</span> &gt; <span class=\"kw-ttt\">cotrimoxazole</span> &gt; amox-ac. clavulanique &gt; FQ &gt; <span class=\"kw-ttt\">céfixime</span> &gt; <span class=\"kw-ttt\">ceftriaxone</span>.</p>\n      <ul>\n        <li><strong>Durée :</strong> <span class=\"kw-chiffre\">10 jours</span> (HAS) ; <span class=\"kw-chiffre\">7 jours</span> si FQ ou β-lactamine parentérale.</li>\n        <li><strong><span class=\"kw-def\">Surveillance</span> :</strong> <span class=\"kw-clinique\">réévaluation clinique</span> à <span class=\"kw-chiffre\">72 h</span>. Si favorable → <span class=\"kw-alerte\">pas d'ECBU de contrôle</span> ❌. Si défavorable → <span class=\"kw-bio\">ECBU</span> + uroscanner.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-alerte\">Hospitalisation</span></strong> si : forme <span class=\"kw-alerte\">hyperalgique</span>, <span class=\"kw-clinique\">vomissements</span> empêchant le per os, <span class=\"kw-alerte\">décompensation</span> de <span class=\"kw-def\">comorbidité</span>, doute diagnostique, contexte social/observance défavorable.\n      </div>","frequence":1},{"id":"161-12","rang":"B","rubrique":"Prise en charge","titre":"Connaître le principe de la prise en charge des pyélonéphrites aiguës compliquées","contenu":"<p>« PNA compliquée » = <span class=\"kw-def\">PNA à risque de complication</span> et/ou <span class=\"kw-alerte\">PNA grave</span>. La <span class=\"kw-alerte\">PNA obstructive fébrile</span> (colique néphrétique fébrile) est la forme la plus fréquente et la plus mortelle.</p>\n      <table >\n        <thead><tr><th></th><th>PNA à risque de complication</th><th>PNA grave</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Bilan</strong></td>\n            <td><span class=\"kw-bio\">ECBU, CRP, créatinine, urée</span><br><span class=\"kw-imagerie\">Uroscanner &lt; 24 h</span> (écho si CI)</td>\n            <td><span class=\"kw-bio\">NFS, CRP, créat, urée, lactate, hémocultures</span><br><span class=\"kw-imagerie\">Uroscanner &lt; 24 h</span></td>\n          </tr>\n          <tr>\n            <td><strong>ATB probabiliste</strong></td>\n            <td><span class=\"kw-ttt\">FQ per os</span> ou <span class=\"kw-ttt\">C3G parentérale</span> (privilégiée si <span class=\"kw-alerte\">hospitalisation</span>)</td>\n            <td><span class=\"kw-ttt\">C3G parentérale + amikacine</span><br>Si FR d'<span class=\"kw-bio\">EBLSE</span> : <span class=\"kw-ttt\">carbapénème + amikacine</span></td>\n          </tr>\n          <tr>\n            <td><strong>Durée</strong></td>\n            <td><span class=\"kw-chiffre\">10-14 jours</span> (21 j si <span class=\"kw-clinique\">abcès</span>)</td>\n            <td><span class=\"kw-ttt\">Amikacine</span> <span class=\"kw-chiffre\">1-3 j</span> ; total <span class=\"kw-chiffre\">10-14 j</span> (21 j si <span class=\"kw-clinique\">abcès</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>🔥 PNA obstructive = <span class=\"kw-alerte\">urgence</span> médico-chirurgicale</strong> — devant une <span class=\"kw-imagerie\">dilatation des cavités pyélocalicielles</span>, le <span class=\"kw-alerte\">drainage des urines</span> est impératif sans délai : <span class=\"kw-ttt\">sonde JJ</span> / sonde urétérale rétrograde, ou <span class=\"kw-ttt\">néphrostomie percutanée</span> échoguidée. L'ATB seule ne suffit jamais.\n      </div>\n      <p>Complications à connaître : <span class=\"kw-alerte\">abcès rénal</span>, <span class=\"kw-clinique\">phlegmon</span> péri-néphrétique, pyonéphrose, <span class=\"kw-alerte\">sepsis/choc septique</span>, <span class=\"kw-clinique\">pyélonéphrite</span> chronique (fibrose, IRC).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-clinique\">Sepsis</span> et <span class=\"kw-alerte\">choc septique</span> de l'enfant et de l'adulte · 265 — Lithiase urinaire</em></p>","frequence":6},{"id":"161-13","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les critères diagnostiques des infections urinaires masculines (cliniques, biologiques, radiologiques)","contenu":"<p>Toute IU de l'homme est classée <strong>au minimum « à risque de complication »</strong> car la <span class=\"kw-clinique\">prostate est potentiellement infectée</span>. <span class=\"kw-clinique\">Les</span> tableaux (<span class=\"kw-clinique\">prostatite</span>, orchi-épididymite, PNA) sont regroupés sous le terme d'<span class=\"kw-def\">IU masculine</span> et traités identiquement.</p>\n      <p><strong>Clinique</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Syndrome infectieux</span> (<span class=\"kw-clinique\">fièvre</span>, frissons) + <span class=\"kw-clinique\">SFU</span> (brûlures, pollakiurie, dysurie, voire <span class=\"kw-alerte\">RAU</span>).</li>\n        <li><span class=\"kw-clinique\">Douleurs pelviennes</span> indépendantes des mictions (périnéales, urétrales, rectales).</li>\n        <li><span class=\"kw-clinique\">TR</span> : prostate <span class=\"kw-clinique\">augmentée de volume, douloureuse, « succulente »</span>, régulière.</li>\n        <li>Formes trompeuses : « <span class=\"kw-alerte\">toute fièvre inexpliquée chez l'homme jeune</span> doit faire rechercher une IU » (TR parfois normal).</li>\n      </ul>\n      <p><strong>Biologie · imagerie</strong></p>\n      <ul>\n        <li><span class=\"kw-bio\">ECBU</span> systématique — seuil de bactériurie abaissé à <span class=\"kw-chiffre\">10³ UFC/mL</span> ; <span class=\"kw-bio\">hémocultures si fièvre</span>.</li>\n        <li><span class=\"kw-imagerie\">Échographie sus-pubienne &lt; 24 h</span> ; <span class=\"kw-ci\">voie endorectale contre-indiquée à la phase aiguë</span> (très douloureuse).</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège</strong> — aucun examen clinique ni imagerie ne permet d'<span class=\"kw-alerte\">écarter l'atteinte prostatique</span> : elle est toujours prise en compte (choix ATB à bonne diffusion, durée longue, bilan urologique).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 50 — Pathologie génito-scrotale chez le garçon et chez l'homme · 127 — Hypertrophie bénigne de la prostate</em></p>","frequence":3},{"id":"161-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités du traitement des infections urinaires masculines et connaître les modalités de leur prévention","contenu":"<p>Le traitement vise un ATB à <strong>bonne diffusion prostatique</strong> et une <strong>durée longue</strong>.</p>\n      <p><strong><span class=\"kw-ttt\">Antibiothérapie</span> documentée (ordre de choix)</strong></p>\n      <ol>\n        <li><span class=\"kw-ttt\"><strong>Fluoroquinolone per os</strong></span> (<span class=\"kw-ttt\">ciprofloxacine</span>, <span class=\"kw-ttt\">lévofloxacine</span>) — <strong>à privilégier</strong> (excellente diffusion prostatique).</li>\n        <li><span class=\"kw-ttt\">Cotrimoxazole per os</span> — seulement si souche sensible (résistances en France).</li>\n      </ol>\n      <p>Probabiliste (formes symptomatiques) : <span class=\"kw-ttt\">C3G IV</span> ou FQ si <span class=\"kw-clinique\">fièvre</span>/RAU/immunodépression ; <span class=\"kw-ttt\">C3G IV + amikacine</span> (± couverture <span class=\"kw-bio\">EBLSE</span>) si <span class=\"kw-alerte\">sepsis/choc</span>.</p>\n      <ul>\n        <li><strong>Durée :</strong> <span class=\"kw-chiffre\">≥ 14 jours</span> ; <span class=\"kw-chiffre\">21 jours</span> à discuter si autre ATB, lithiase, immunodépression, trouble urinaire.</li>\n        <li><strong><span class=\"kw-ttt\">Drainage</span> si <span class=\"kw-alerte\">RAU</span> :</strong> <span class=\"kw-ttt\">cathéter sus-pubien</span> préféré (sondage urétral <span class=\"kw-ci\">CI relative</span> sur <span class=\"kw-clinique\">prostatite</span>).</li>\n        <li><span class=\"kw-ci\">AINS contre-indiqués</span> ; α-bloquant possible si dysurie.</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Prévention / bilan étiologique</strong>\n        <ul>\n          <li>1ᵉʳ épisode : rechercher cliniquement une <span class=\"kw-etio\">anomalie du bas appareil</span> (dysurie, nycturie, anomalie au TR).</li>\n          <li>Anomalie suspectée (surtout &gt;<span class=\"kw-chiffre\"> 50 ans</span>) ou <span class=\"kw-clinique\">2ᵉ épisode</span> → avis urologue + <span class=\"kw-imagerie\">échographie avec résidu post-mictionnel</span> + débitmétrie.</li>\n          <li><span class=\"kw-ttt\">Antibioprophylaxie</span> par FQ <span class=\"kw-chiffre\">1-2 h</span> avant <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">biopsies prostatiques</span> / gestes endo-urétraux.</li>\n        </ul>\n      </div>","frequence":2},{"id":"161-15","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités du traitement des infections urinaires au cours de la grossesse et son suivi","contenu":"<p>La <span class=\"kw-etio\">grossesse</span> est un FR de complication : <strong>toute IU y est « à risque »</strong> et impose un <span class=\"kw-def\">suivi</span> rapproché (risque de <span class=\"kw-clinique\">PNA</span>, de <span class=\"kw-alerte\">prématurité</span>).</p>\n      <p><strong><span class=\"kw-def\">Dépistage</span> et <span class=\"kw-def\">suivi</span></strong></p>\n      <ul>\n        <li><span class=\"kw-bio\">ECBU mensuel</span> systématique à partir du <span class=\"kw-chiffre\">4ᵉ mois</span> (<span class=\"kw-bio\">BU</span> mensuelle avant).</li>\n        <li><span class=\"kw-def\">Colonisation urinaire gravidique</span> = bactériurie <span class=\"kw-chiffre\">≥ 10⁵ UFC/mL</span> sur <span class=\"kw-chiffre\">2 ECBU</span> → <strong>à traiter</strong> (seule <span class=\"kw-etio\">colonisation</span> systématiquement traitée).</li>\n        <li><span class=\"kw-bio\">ECBU de contrôle</span><span class=\"kw-chiffre\"> 8-10 jours</span> après la fin du traitement, puis mensuel.</li>\n      </ul>\n      <table >\n        <thead><tr><th>Forme</th><th>Principe</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Colonisation</span></td><td>Traiter d'emblée selon l'<span class=\"kw-bio\">antibiogramme</span> (pas de probabiliste).</td></tr>\n          <tr><td><span class=\"kw-clinique\">Cystite gravidique</span></td><td>Traiter sans attendre l'<span class=\"kw-bio\">antibiogramme</span>, puis adapter ; <span class=\"kw-bio\">ECBU</span> de contrôle.</td></tr>\n          <tr><td><span class=\"kw-alerte\">PNA gravidique</span></td><td><span class=\"kw-alerte\">Hospitalisation</span>, <span class=\"kw-ttt\">C3G parentérale</span>, <span class=\"kw-clinique\">surveillance materno-fœtale</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Molécules</strong> — le détail des antibiotiques utilisables et <span class=\"kw-ci\">contre-indiqués</span> pendant la <span class=\"kw-ci\">grossesse</span> est développé dans l'item dédié.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 28 — Principales complications de la <span class=\"kw-ci\">grossesse</span> · 27 — Connaître <span class=\"kw-clinique\">les</span> particularités de la prescription chez la femme enceinte</em></p>","frequence":1},{"id":"161-16","rang":"A","rubrique":"Prise en charge","titre":"Connaître les spécificités de l'infection urinaire de la personne âgée","contenu":"<p>L'IU est la <span class=\"kw-chiffre\">2ᵉ cause</span> d'infection du sujet âgé. Le défi est de la <strong>distinguer d'une simple <span class=\"kw-def\">colonisation</span></strong>, très fréquente sur ce <span class=\"kw-def\">terrain</span>.</p>\n      <p><strong>Spécificités microbiologiques</strong></p>\n      <ul>\n        <li><span class=\"kw-etio\">E. coli &lt; 50 %</span>, plus de <span class=\"kw-etio\">Gram +</span>, fort taux de résistance en institution.</li>\n        <li>FR nombreux : apports hydriques insuffisants, <span class=\"kw-etio\">pathologie prostatique</span>, <span class=\"kw-etio\">ménopause</span>, <span class=\"kw-clinique\">incontinence</span>, <span class=\"kw-etio\">vessie neurologique</span>, <span class=\"kw-etio\">anticholinergiques</span>.</li>\n      </ul>\n      <p><strong>Particularités diagnostiques</strong></p>\n      <ul>\n        <li><span class=\"kw-alerte\">Fièvre absente dans 30 %</span> des cas, ou <span class=\"kw-clinique\">fièvre</span> nue ; douleurs abdominales plutôt que lombaires (<span class=\"kw-chiffre\">20 %</span>).</li>\n        <li>Présentation trompeuse : <span class=\"kw-clinique\">confusion</span>, <span class=\"kw-clinique\">chutes</span>, <span class=\"kw-clinique\">AEG</span>, <span class=\"kw-clinique\">syndrome de glissement</span>, <span class=\"kw-alerte\">décompensation</span> de <span class=\"kw-def\">comorbidité</span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong>⚠️ Piège majeur</strong> — devant une <span class=\"kw-clinique\">fièvre</span>, une <span class=\"kw-bio\">bactériurie + leucocyturie sans signe urinaire</span> <strong>ne permet PAS</strong> de rattacher la fièvre à une IU (<span class=\"kw-etio\">colonisation</span> et <span class=\"kw-bio\">leucocyturie</span> sont banales ici). Seule la <strong>modification récente</strong> des signes urinaires doit alerter.\n      </div>\n      <p>Pas de traitement court ; <strong>adapter la posologie</strong> à la <span class=\"kw-bio\">clairance de la créatinine</span> (<span class=\"kw-bio\">Cockcroft / MDRD</span>).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 130 — Prise en charge globale du sujet âgé · 119 — Vieillissement · 351 — Confusion</em></p>","frequence":2},{"id":"161-17","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir évoquer une infection urinaire de l'enfant : enquête clinique","contenu":"<p>Chez l'enfant, l'IU est très fréquente (<span class=\"kw-chiffre\">7,5 %</span> des fièvres avant <span class=\"kw-chiffre\">2 ans</span>) et le tableau est <strong>peu spécifique</strong> chez le petit. Avant <span class=\"kw-chiffre\">1 an</span>, c'est une <span class=\"kw-clinique\">PNA</span> dans <span class=\"kw-chiffre\">95 %</span> des cas.</p>\n      <div class=\"callout callout-danger\">\n        <strong>Dogme — évoquer une IU devant :</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Fièvre sans point d'appel avant l'âge de 3 mois</span></li>\n          <li><span class=\"kw-clinique\">Fièvre</span> isolée persistante <span class=\"kw-chiffre\">&gt; 48 h</span></li>\n          <li>Signes fonctionnels urinaires</li>\n          <li>ATCD de PNA ou <span class=\"kw-etio\">malformation des voies urinaires</span></li>\n        </ul>\n      </div>\n      <table >\n        <thead><tr><th>Critère</th><th>PNA</th><th><span class=\"kw-clinique\">Cystite</span> aiguë</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Fièvre / signes généraux</span></td><td>+++</td><td>0</td></tr>\n          <tr><td><span class=\"kw-clinique\">Signes fonctionnels urinaires</span></td><td>+</td><td>+++</td></tr>\n          <tr><td><span class=\"kw-clinique\">Douleur</span></td><td>Lombo-abdominale</td><td>Hypogastrique</td></tr>\n          <tr><td><span class=\"kw-clinique\">Palpation lombaire</span></td><td>Douloureuse (inconstant)</td><td>Indolore</td></tr>\n        </tbody>\n      </table>\n      <p>Selon l'âge : <span class=\"kw-clinique\">PNA du nouveau-né</span> (troubles digestifs, <span class=\"kw-clinique\">ictère</span>, <span class=\"kw-clinique\">déshydratation</span>) ; <span class=\"kw-clinique\">nourrisson</span> (<span class=\"kw-clinique\">fièvre</span> inexpliquée + troubles hémodynamiques) ; <span class=\"kw-clinique\">grand enfant</span> (tableau adulte). La <span class=\"kw-clinique\">cystite</span> touche surtout la fille (SFU intenses, douleur hypogastrique, sans fièvre).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 51 — Troubles de la miction chez l'enfant · 147 — <span class=\"kw-clinique\">Fièvre</span> aiguë chez l'enfant et l'adulte</em></p>","frequence":1},{"id":"161-18","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les modalités de prescription du ou des examens complémentaires chez l'enfant","contenu":"<p>Le diagnostic d'IU de l'enfant ne peut être affirmé que par l'<span class=\"kw-bio\">examen des urines</span> ; la <strong>qualité du prélèvement</strong> conditionne l'interprétation.</p>\n      <table >\n        <thead><tr><th>Mode de recueil</th><th>À retenir</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Collecteur adhésif</span></td><td>Le plus utilisé mais <span class=\"kw-alerte\">VPP médiocre</span> (jusqu'à<span class=\"kw-chiffre\"> 50 %</span> de faux positifs) → <strong>utile seulement s'il est négatif</strong> ; pose <span class=\"kw-chiffre\">≤ 30 min</span>.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Milieu de jet</span></td><td>À privilégier (non invasif), VPP meilleure (~<span class=\"kw-chiffre\">20 %</span> FP).</td></tr>\n          <tr><td><span class=\"kw-clinique\">Cathétérisme urétral</span></td><td>Alternative avant <span class=\"kw-chiffre\">2 ans</span>, évite la contamination (<span class=\"kw-chiffre\">10 %</span> FP).</td></tr>\n          <tr><td><span class=\"kw-clinique\">Ponction sus-pubienne</span></td><td>Échoguidée, indications limitées.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>Règle d'âge pour la <span class=\"kw-bio\">BU</span></strong>\n        <ul>\n          <li><span class=\"kw-clinique\">&gt; 1 mois</span> : <span class=\"kw-bio\">BU</span> d'abord ; si positive → <span class=\"kw-bio\">ECBU</span>. <span class=\"kw-bio\">BU</span> négative = VPN <span class=\"kw-chiffre\">97 %</span> → pas d'<span class=\"kw-bio\">ECBU</span>.</li>\n          <li><span class=\"kw-alerte\">&lt; 1 mois</span> : <span class=\"kw-bio\">ECBU d'emblée</span> systématique (<span class=\"kw-bio\">BU</span> peu sensible à cet âge).</li>\n        </ul>\n      </div>\n      <ul>\n        <li>Seuils de bactériurie : <span class=\"kw-chiffre\">10⁴</span> (collecteur), <span class=\"kw-chiffre\">10³</span> (jet/cathéter), <span class=\"kw-chiffre\">10²</span> (<span class=\"kw-ttt\">ponction</span> sus-pubienne).</li>\n        <li><span class=\"kw-bio\">Hémocultures</span> si PNA &lt;<span class=\"kw-chiffre\"> 3 mois</span> ou <span class=\"kw-alerte\"><span class=\"kw-def\">critère de</span> gravité</span> ; <span class=\"kw-bio\">PL</span> si PNA &lt;<span class=\"kw-chiffre\"> 6 semaines</span> (risque de <span class=\"kw-alerte\">méningite</span>).</li>\n        <li><span class=\"kw-imagerie\">Échographie réno-vésicale</span> = <strong>seul examen d'imagerie de 1ʳᵉ intention</strong> : systématique au 1ᵉʳ épisode de PNA. <span class=\"kw-ci\">Pas de scintigraphie ni d'uro-TDM/IRM</span> en routine.</li>\n      </ul>","frequence":1},{"id":"161-19","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de prise en charge thérapeutique d'une infection urinaire de l'enfant","contenu":"<p>Deux principes propres à l'enfant : <strong>pas de traitement « minute »</strong> (non validé chez l'enfant non pubère) et <strong>pas de quinolones</strong> sauf impasse.</p>\n      <table >\n        <thead><tr><th>Forme</th><th>ATB initiale</th><th>Durée</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Cystite aiguë</span></td>\n            <td><span class=\"kw-ttt\">Cotrimoxazole</span>, <span class=\"kw-ttt\">céfixime</span> ou <span class=\"kw-ttt\">amox-ac. clavulanique</span> per os (ambulatoire)</td>\n            <td><span class=\"kw-chiffre\">3-5 jours</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">PNA sans gravité</span> (&gt;<span class=\"kw-chiffre\"> 3 mois</span>)</td>\n            <td>Monothérapie : <span class=\"kw-ttt\">céfixime</span> per os, ou <span class=\"kw-ttt\">C3G IV</span>, ou <span class=\"kw-ttt\">amikacine</span> ; relais selon <span class=\"kw-bio\">ECBU</span></td>\n            <td><span class=\"kw-chiffre\">10 jours</span> (7 j si FQ)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">PNA grave</span> ou &lt;<span class=\"kw-chiffre\"> 3 mois</span></td>\n            <td><span class=\"kw-alerte\">Hospitalisation</span> : <span class=\"kw-ttt\">C3G IV + amikacine</span> ; relais oral à 2-4 j</td>\n            <td><span class=\"kw-chiffre\">10-14 jours</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>⚠️ Piège PK/PD</strong> — même si l'<span class=\"kw-bio\">antibiogramme</span> montre <span class=\"kw-etio\">E. coli</span> sensible à l'<span class=\"kw-ci\">amoxicilline</span> et à l'<span class=\"kw-ci\">amox-ac. clavulanique</span>, leurs propriétés <strong>n'autorisent pas leur usage dans la PNA</strong>. Exception : IU à <span class=\"kw-etio\">entérocoque</span> (<span class=\"kw-etio\">streptocoque</span> D) → <span class=\"kw-ttt\">amoxicilline</span> (PK/PD excellentes).\n      </div>\n      <ul>\n        <li><span class=\"kw-clinique\">Hospitalisation systématique si &lt; 3 mois</span>, même sans autre <span class=\"kw-alerte\"><span class=\"kw-def\">critère de</span> gravité</span>.</li>\n        <li><span class=\"kw-ci\">Allergie</span> aux β-lactamines → <span class=\"kw-ttt\">aminoside</span> en monothérapie IV (<span class=\"kw-ttt\">amikacine</span> couvre <span class=\"kw-chiffre\">95 %</span> des <span class=\"kw-etio\">E. coli</span> <span class=\"kw-bio\">BLSE</span>).</li>\n        <li><strong>Pas d'<span class=\"kw-bio\">ECBU</span> de contrôle</strong> systématique ; <span class=\"kw-def\">surveillance</span> clinique, réévaluation à <span class=\"kw-chiffre\">J2</span> si ambulatoire.</li>\n      </ul>","frequence":0},{"id":"161-20","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires à réaliser dans les infections urinaires récidivantes","contenu":"<p><strong>Chez l'adulte</strong> (femme), le bilan d'une <span class=\"kw-clinique\">cystite</span> récidivante (<span class=\"kw-chiffre\">≥ 4 épisodes/an</span>) vise à distinguer rechute et réinfection :</p>\n      <ul>\n        <li><span class=\"kw-bio\">ECBU</span> dès le 4ᵉ épisode : <span class=\"kw-def\">cystite à rechute</span> (même germe → chercher une cause de complication) <span class=\"kw-bio\">vs</span> <span class=\"kw-def\">infections itératives</span> (germes différents).</li>\n        <li>Examen <span class=\"kw-clinique\">pelvien et urétral</span> ; <span class=\"kw-bio\">débitmétrie</span>, <span class=\"kw-bio\">résidu post-mictionnel</span>, catalogue mictionnel (1ʳᵉ intention).</li>\n        <li><span class=\"kw-ci\">Pas d'imagerie du haut appareil</span> chez la femme non ménopausée à examen normal.</li>\n      </ul>\n      <p><strong>Chez l'enfant</strong>, une PNA récidivante fait rechercher un <span class=\"kw-def\">reflux vésico-urétéral (RVU)</span> ou une <span class=\"kw-etio\">uropathie malformative</span> :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">Cystographie rétrograde</span> = examen objectivant le RVU ; indiquée si <span class=\"kw-imagerie\">anomalies échographiques</span> à préciser ou <span class=\"kw-clinique\">épisodes répétés de PNA</span>.</li>\n        <li><span class=\"kw-alerte\">Non systématique dès le 1ᵉʳ épisode</span> : le RVU est intermittent et s'améliore souvent avec la croissance ; la <span class=\"kw-ttt\">chirurgie</span> ne concerne que <span class=\"kw-clinique\">les</span> RVU malformatifs de haut <span class=\"kw-def\">grade</span>.</li>\n        <li>Penser aux <span class=\"kw-alerte\">valves de l'urètre postérieur</span> chez le nourrisson garçon (dilatation urétéro-pyélo-calicielle, vessie de lutte → <span class=\"kw-alerte\">urgence</span> chirurgicale).</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 51 — Troubles de la miction chez l'enfant · 265 — Lithiase urinaire</em></p>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/vesicoureteric-reflux","label":"Radiopaedia : Vesicoureteric reflux"},{"href":"https://radiopaedia.org/articles/posterior-urethral-valves","label":"Radiopaedia : Posterior urethral valves"}]},{"id":"161-21","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement des cystites récidivantes (curatif médical, préventif)","contenu":"<p>La <span class=\"kw-clinique\">cystite</span> récidivante sans FR de complication relève d'une stratégie en trois temps : <strong>curatif des poussées, préventif non antibiotique, puis <span class=\"kw-ttt\">antibioprophylaxie</span> en dernier recours</strong>.</p>\n      <p><strong>Curatif</strong></p>\n      <ul>\n        <li>Traitement de chaque épisode identique à la <span class=\"kw-clinique\">cystite</span> simple : <span class=\"kw-ttt\">fosfomycine-trométamol</span> (dose unique) ou <span class=\"kw-ttt\">pivmécillinam</span>.</li>\n        <li>Possible <span class=\"kw-clinique\">auto-médication sur BU positive</span> chez une patiente sélectionnée et éduquée (<span class=\"kw-def\">réévaluation</span> <span class=\"kw-chiffre\">≥ 2</span>×/an ; <span class=\"kw-ci\">nitrofurantoïne exclue</span> dans cette indication).</li>\n      </ul>\n      <p><strong>Préventif non antibiotique</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Mesures d'hygiène</span>, arrêt des <span class=\"kw-etio\">spermicides</span>.</li>\n        <li><span class=\"kw-ttt\">Canneberge</span> (<span class=\"kw-chiffre\">≥ 36 mg</span>/j de proanthocyanidine A) — prévention des récidives à <span class=\"kw-etio\">E. coli</span>, faible niveau de preuve (pas le jus).</li>\n        <li><span class=\"kw-ttt\">Œstrogènes locaux</span> chez la <span class=\"kw-etio\">femme ménopausée</span> (après avis gynécologique).</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-ttt\">Antibioprophylaxie</span></strong> (si <span class=\"kw-chiffre\">≥ 1 cystite/mois</span>, après échec des autres mesures)\n        <ul>\n          <li><span class=\"kw-clinique\">Cystite post-coïtale</span> : <span class=\"kw-ttt\">fosfomycine</span> (ou <span class=\"kw-ttt\">cotrimoxazole</span>) dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 h</span> autour du rapport.</li>\n          <li>Autres : <span class=\"kw-ttt\">fosfomycine 1×/semaine</span> ou <span class=\"kw-ttt\">cotrimoxazole</span> 1×/j au coucher.</li>\n          <li><strong><span class=\"kw-def\">Réévaluation</span> semestrielle</strong> obl<span class=\"kw-chiffre\">iga</span>toire — l'<span class=\"kw-ttt\">antibioprophylaxie</span> n'est jamais la norme.</li>\n        </ul>\n      </div>","frequence":1},{"id":"161-22","rang":"B","rubrique":"Epidémiologie","titre":"Infections urinaires de l'enfant : connaître l'épidémiologie","contenu":"<p><span class=\"kw-clinique\">Les</span> IU sont parmi les <strong>infections bactériennes les plus fréquentes en pédiatrie</strong>.</p>\n      <ul>\n        <li>Responsables de <span class=\"kw-chiffre\">7,5 %</span> des fièvres avant <span class=\"kw-chiffre\">2 ans</span> ; fréquence globale <span class=\"kw-chiffre\">2-20 %</span> selon âge et sexe.</li>\n        <li><span class=\"kw-clinique\">Sex-ratio</span> : prédominance <strong>masculine</strong> <span class=\"kw-clinique\">les</span> premiers mois de vie, puis <strong>féminine</strong> ensuite.</li>\n        <li>Avant <span class=\"kw-chiffre\">1 an</span>, l'IU est une <span class=\"kw-clinique\">PNA dans 95 %</span> des cas.</li>\n      </ul>\n      <p><strong>Microbiologie</strong></p>\n      <ul>\n        <li><span class=\"kw-etio\">E. coli</span> ≈ <span class=\"kw-chiffre\">80 %</span> ; résistance/intermédiaire à l'<span class=\"kw-ci\">amoxicilline</span> dans <span class=\"kw-chiffre\">50 %</span> des souches, au <span class=\"kw-ci\">cotrimoxazole</span> dans <span class=\"kw-chiffre\">20-30 %</span>.</li>\n        <li>Souches <span class=\"kw-bio\">BLSE</span> communautaires en hausse mais <span class=\"kw-chiffre\">&lt; 10 %</span> en France.</li>\n        <li>Autres : <span class=\"kw-etio\">Proteus mirabilis</span> (<span class=\"kw-chiffre\">10 %</span>), <span class=\"kw-etio\">entérocoques</span>, <span class=\"kw-etio\">Klebsiella</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Terrains à risque</strong> — <span class=\"kw-etio\">uropathie malformative</span>, <span class=\"kw-etio\">absence de circoncision</span> chez le garçon, troubles de l'élimination (<span class=\"kw-clinique\">constipation</span>, vessie instable).\n      </div>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Forme la plus grave :</strong> la <span class=\"kw-etio\">PNA obstructive</span> (colique néphrétique fébrile) est une <span class=\"kw-alerte\">urgence médico-chirurgicale</span> — forme grave la plus fréquente et la plus mortelle.<br><strong>1er geste si <span class=\"kw-alerte\">sepsis</span> :</strong> <span class=\"kw-bio\">ECBU</span> + <span class=\"kw-bio\">hémocultures</span> <span class=\"kw-ttt\">avant toute antibiothérapie</span>, puis <span class=\"kw-ttt\">ATB probabiliste</span> en <span class=\"kw-alerte\">urgence</span>.<br><strong><span class=\"kw-ttt\">Drainage</span> :</strong> <span class=\"kw-ttt\">drainage urinaire en urgence</span> (<span class=\"kw-ttt\">sonde JJ</span> ou <span class=\"kw-ttt\">néphrostomie percutanée</span>) si <span class=\"kw-radio\">dilatation des cavités pyélocalicielles</span>.<br><strong>Imagerie :</strong> <span class=\"kw-imagerie\">uroscanner</span> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">&lt; 24h</span> (PNA à risque / grave) ; <span class=\"kw-imagerie\">échographie</span> <span class=\"kw-chiffre\">&lt; 24h</span> si PNA hyperalgique.<br><strong><span class=\"kw-clinique\">Cystite</span> :</strong> jamais une urgence — <span class=\"kw-alerte\">la cystite n'est jamais grave</span>.</p>","hospit":"<p><strong>Ambulatoire :</strong> toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">cystites</span> (simples, à risque, récidivantes) et la <span class=\"kw-clinique\">PNA simple</span> le plus souvent (voie orale privilégiée).<br><strong><span class=\"kw-alerte\">Hospitalisation</span> (PNA) :</strong> <span class=\"kw-alerte\">PNA grave</span>, <span class=\"kw-alerte\">PNA hyperalgique</span>, <span class=\"kw-alerte\">vomissements</span> empêchant la voie orale, <span class=\"kw-alerte\">décompensation</span> de <span class=\"kw-def\">comorbidité</span>, doute diagnostique, doute sur l'observance.<br><strong>Hospitalisation (IU masculine) :</strong> <span class=\"kw-alerte\">rétention aiguë d'urine</span>, <span class=\"kw-alerte\">sepsis / choc septique</span>, <span class=\"kw-alerte\">immunodépression profonde</span>, forme hyperalgique, <span class=\"kw-clinique\">vomissements</span>.<br><strong>Soins critiques :</strong> <span class=\"kw-alerte\">sepsis</span> ou <span class=\"kw-alerte\">choc septique</span> (PNA ou IU masculine grave).<br><strong>Enfant :</strong> hospitalisation systématique si <span class=\"kw-chiffre\">âge &lt; 3 mois</span> ou présence d'un <span class=\"kw-alerte\"><span class=\"kw-def\">critère de</span> gravité</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Sepsis</span> ou <span class=\"kw-alerte\">choc septique</span> (PNA grave si <span class=\"kw-chiffre\">qSOFA &gt; 2</span>)</li><li><span class=\"kw-alerte\">Indication de geste urologique</span> : <span class=\"kw-ttt\">drainage chirurgical</span> ou <span class=\"kw-ttt\">radiologie interventionnelle</span> (hors sondage vésical simple)</li><li><span class=\"kw-etio\">PNA obstructive</span> sur <span class=\"kw-radio\">dilatation des cavités pyélocalicielles</span> (rétention purulente sur lithiase, <span class=\"kw-clinique\">abcès</span>, PNA emphysémateuse)</li><li>Forme <span class=\"kw-alerte\">hyperalgique</span>, non calmée par <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">antalgiques</span> usuels</li><li><span class=\"kw-alerte\">Rétention aiguë d'urine</span> (IU masculine)</li><li>Seules la <span class=\"kw-clinique\">PNA</span> et l'<span class=\"kw-clinique\">IU masculine</span> peuvent être graves — <span class=\"kw-alerte\">la cystite n'est jamais grave</span></li><li>Enfant : <span class=\"kw-chiffre\">âge &lt; 3 mois</span>, signes de <span class=\"kw-alerte\">déshydratation</span>, <span class=\"kw-clinique\">altération de l'état général</span></li></ul>","principes":"<p>Le spectre de l'<span class=\"kw-ttt\">ATB probabiliste</span> doit toujours inclure <span class=\"kw-etio\">E. coli</span> ; <span class=\"kw-ttt\">ECBU avant toute antibiothérapie</span>, sauf <span class=\"kw-clinique\">cystite</span> simple où la <span class=\"kw-bio\">BU</span> suffit.</p><p><strong><span class=\"kw-clinique\">Cystite</span> aiguë simple</strong></p><p>Objectif = soulager <span class=\"kw-clinique\">les</span> symptômes, pas prévenir une PNA.</p><ul><li><span class=\"kw-bio\">BU</span> seule — <span class=\"kw-bio\">ECBU non nécessaire</span></li><li>1re intention : <span class=\"kw-ttt\">fosfomycine-trométamol</span> en <span class=\"kw-chiffre\">dose unique</span></li><li><span class=\"kw-chiffre\">2e intention</span> : <span class=\"kw-ttt\">pivmécillinam</span> pendant <span class=\"kw-chiffre\">3-5 jours</span></li><li><span class=\"kw-chiffre\">3e intention</span> (dernier recours) : <span class=\"kw-ttt\">nitrofurantoïne</span> <span class=\"kw-chiffre\">5 jours</span></li></ul><p><strong><span class=\"kw-clinique\">Cystite</span> à risque de complication</strong></p><ul><li><span class=\"kw-bio\">ECBU systématique</span></li><li>Peu symptomatique → <span class=\"kw-ttt\">ATB différée adaptée</span> : <span class=\"kw-ttt\">amoxicilline</span> <span class=\"kw-chiffre\">7 j</span> (1re), <span class=\"kw-ttt\">pivmécillinam</span> <span class=\"kw-chiffre\">7 j</span>, <span class=\"kw-ttt\">nitrofurantoïne</span> <span class=\"kw-chiffre\">7 j</span></li><li>Symptômes gênants → probabiliste : <span class=\"kw-ttt\">nitrofurantoïne</span> <span class=\"kw-chiffre\">7 j</span> puis <span class=\"kw-ttt\">fosfomycine</span> dose unique</li></ul><p><strong>PNA (simple / à risque / grave)</strong></p><p>Risque d'<span class=\"kw-bio\">EBLSE</span> pris en compte uniquement dans l'ATB probabiliste des IU graves.</p><ul><li>Probabiliste simple : <span class=\"kw-ttt\">fluoroquinolone</span> per os ou <span class=\"kw-ttt\">C3G parentérale</span></li><li>Grave : <span class=\"kw-ttt\">C3G parentérale + amikacine</span> ; si <span class=\"kw-etio\">EBLSE</span> : <span class=\"kw-ttt\">carbapénème + amikacine</span></li><li>Adaptée (1re) : <span class=\"kw-ttt\">amoxicilline</span> pendant <span class=\"kw-chiffre\">10 jours</span></li><li><span class=\"kw-ttt\">Drainage</span> si <span class=\"kw-radio\">dilatation des cavités pyélocalicielles</span></li></ul><p><strong>IU masculine</strong></p><ul><li><span class=\"kw-ttt\">Fluoroquinolone</span> per os à privilégier (excellente diffusion prostatique)</li><li>Durée <span class=\"kw-chiffre\">≥ 14 jours</span> (<span class=\"kw-chiffre\">≥ 21 jours</span> si lithiase / immunodépression / trouble urinaire)</li><li><span class=\"kw-ttt\">ɑ-bloquants</span> si dysurie / RAU ; <span class=\"kw-ci\">AINS contre-indiqués</span></li><li><span class=\"kw-ttt\">Drainage par cathéter sus-pubien</span> si <span class=\"kw-alerte\">RAU</span> (<span class=\"kw-ci\">sondage CI relative en phase aiguë</span>)</li></ul><p><strong><span class=\"kw-ci\">Grossesse</span></strong></p><ul><li><span class=\"kw-bio\">Dépistage de la colonisation</span> : seuil <span class=\"kw-chiffre\">10⁵ UFC/mL</span> sur <span class=\"kw-chiffre\">2 ECBU</span> consécutifs</li><li><span class=\"kw-bio\">ECBU mensuel</span> systématique à partir du <span class=\"kw-chiffre\">4ᵉ mois</span></li></ul><p><strong>Enfant</strong></p><ul><li>PNA avec <span class=\"kw-alerte\"><span class=\"kw-def\">critère de</span> gravité</span> → <span class=\"kw-alerte\">hospitalisation</span>, <span class=\"kw-ttt\">C3G IV + amikacine</span></li><li>PNA sans gravité (<span class=\"kw-chiffre\">&gt; 3 mois</span>) → ambulatoire, monothérapie (<span class=\"kw-ttt\">céfixime</span> per os, <span class=\"kw-ttt\">C3G IV</span> ou <span class=\"kw-ttt\">amikacine</span>)</li><li><span class=\"kw-ci\">Quinolones et traitement minute exclus</span> chez l'enfant non pubère</li></ul>","suivi":"<p><strong>Règle générale :</strong> <span class=\"kw-bio\">pas d'ECBU de contrôle</span> si l'<span class=\"kw-clinique\">évolution</span> est favorable.<br><strong><span class=\"kw-clinique\">Cystite</span> simple :</strong> favorable en <span class=\"kw-chiffre\">2-3 jours</span> ; <span class=\"kw-bio\">ECBU de contrôle</span> seulement si <span class=\"kw-alerte\">échec à 72h</span> ou <span class=\"kw-clinique\">récidive &lt; 2 semaines</span> (récidive dans <span class=\"kw-chiffre\">20-30 %</span>).<br><strong>PNA :</strong> <span class=\"kw-clinique\">réévaluation clinique systématique à 72h</span> ; si <span class=\"kw-clinique\">fièvre</span> persistante <span class=\"kw-chiffre\">&gt; 72h</span> → <span class=\"kw-bio\">ECBU</span> + <span class=\"kw-imagerie\">uroscanner</span>.<br><strong>IU masculine :</strong> favorable à <span class=\"kw-chiffre\">J3</span> → pas de contrôle ; défavorable <span class=\"kw-chiffre\">&gt; 72h</span> → <span class=\"kw-bio\">ECBU</span> + <span class=\"kw-bio\">hémocultures</span> + <span class=\"kw-imagerie\">IRM prostatique</span> (ou <span class=\"kw-imagerie\">échographie</span> endorectale) ; bilan urologique au 1er épisode ou après <span class=\"kw-chiffre\">50 ans</span>.<br><strong>Enfant :</strong> <span class=\"kw-def\">réévaluation</span> à <span class=\"kw-chiffre\">J2</span> si ambulatoire ; pas d'<span class=\"kw-bio\">ECBU</span> de contrôle ; si échec → <span class=\"kw-imagerie\">échographie</span> à la recherche d'un <span class=\"kw-etio\">abcès rénal</span>. <span class=\"kw-def\">Pronostic</span> lié aux <span class=\"kw-etio\">cicatrices parenchymateuses</span>.</p>"},"liensGlobaux":[{"href":"https://www.urofrance.org/lafu-academie/formation-du-college/referentiel-du-college-durologie-6eme-edition/chapitre-11-item-161-infections-urinaires-de-ladulte-et-de-lenfant/","label":"Collège d'Urologie — référentiel 6e éd. (item 161)"},{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-161.pdf","label":"Pilly étudiant 2023 — item 161"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/48.%20Sepsis%20urinaire%20grave.pdf","label":"Collège MIR — Sepsis urinaire grave"},{"href":"https://manuel4.cuen.fr/spip.php?rubrique24","label":"CUEN — manuel de néphrologie (chap. infections urinaires)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"IU symptomatique de l'adulte — BU + clinique ; ECBU sauf cystite simple","detail":"<h4>CAT — <span class=\"kw-clinique\">Infection urinaire</span> de l'adulte — Du symptôme à la décision : cystite <span class=\"kw-bio\">vs</span> PNA <span class=\"kw-bio\">vs</span> IU masculine</h4>","branches":[{"to":"q-sexe","label":"Démarche diagnostique","color":"blue"}]},{"id":"q-sexe","kind":"decision","label":"Homme ? — Le sexe oriente d'emblée la démarche","branches":[{"to":"t-iu-masculine","label":"Oui — homme","color":"amber"},{"to":"q-fievre","label":"Non — femme","color":"blue"}]},{"id":"t-iu-masculine","kind":"terminal","label":"Infection urinaire masculine — Toujours au moins « à risque de complication »","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Syndrome <span class=\"kw-etio\">infectieux</span></span> + SBAU ; <span class=\"kw-clinique\">TR : prostate augmentée, douloureuse, « succulente »</span></li><li>Aucun examen ne permet d'écarter l'<span class=\"kw-etio\">atteinte prostatique</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">ECBU systématique</span> (seuil <span class=\"kw-chiffre\">10³ UFC/mL</span>)</li><li><span class=\"kw-imagerie\">Échographie</span> sus-pubienne <span class=\"kw-chiffre\">&lt; 24h</span> ; <span class=\"kw-bio\">hémocultures</span> si <span class=\"kw-clinique\">fièvre</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Fluoroquinolone</span> per os à privilégier (diffusion prostatique)</li><li>Durée <span class=\"kw-chiffre\">≥ 14 jours</span> (<span class=\"kw-chiffre\">≥ 21 j</span> si compliquée) ; <span class=\"kw-ci\">AINS contre-indiqués</span></li></ul><h4>Conduite</h4><ul><li>Hospit si <span class=\"kw-alerte\">RAU</span>, <span class=\"kw-alerte\">sepsis / choc</span>, <span class=\"kw-alerte\">immunodépression profonde</span>, forme hyperalgique</li><li>Grave → <span class=\"kw-ttt\">C3G IV + amikacine</span> ; <span class=\"kw-ttt\">drainage par cathéter sus-pubien</span> si RAU</li></ul>"},{"id":"q-fievre","kind":"decision","label":"Fièvre / syndrome infectieux ? — Témoigne d'une atteinte parenchymateuse (rein)","branches":[{"to":"q-cystite-fr","label":"Non — SBAU isolés, apyrexie","color":"green"},{"to":"q-pna-strat","label":"Oui — fièvre, frissons, douleur lombaire","color":"amber"}]},{"id":"q-cystite-fr","kind":"decision","label":"FR de complication ? — Anomalie de l'arbre urinaire, > 75 ans, grossesse, IRC sévère, immunodépression","branches":[{"to":"t-cystite-simple","label":"Non — femme sans FR","color":"green"},{"to":"t-cystite-risque","label":"Oui — FR de complication","color":"amber"}]},{"id":"t-cystite-simple","kind":"terminal","label":"Cystite aiguë simple — Ambulatoire — jamais grave","color":"green","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">BU</span> seule — <span class=\"kw-bio\">ECBU non nécessaire</span>, pas d'imagerie</li></ul><h4>Traitement</h4><ul><li>1re : <span class=\"kw-ttt\">fosfomycine-trométamol</span> en <span class=\"kw-chiffre\">dose unique</span></li><li>2e : <span class=\"kw-ttt\">pivmécillinam</span> <span class=\"kw-chiffre\">3-5 j</span> ; 3e : <span class=\"kw-ttt\">nitrofurantoïne</span> <span class=\"kw-chiffre\">5 j</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Favorable en <span class=\"kw-chiffre\">2-3 j</span> ; <span class=\"kw-bio\">ECBU de contrôle</span> si échec à<span class=\"kw-chiffre\"> 72h</span> ou récidive <span class=\"kw-chiffre\">&lt; 2 semaines</span></li></ul>"},{"id":"t-cystite-risque","kind":"terminal","label":"Cystite à risque de complication — Ambulatoire avec ECBU","color":"amber","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">ECBU systématique</span></li></ul><h4>Traitement</h4><ul><li>Peu symptomatique → <span class=\"kw-ttt\">ATB différée adaptée</span> (<span class=\"kw-ttt\">amoxicilline</span> <span class=\"kw-chiffre\">7 j</span> en 1re)</li><li>Gênante → probabiliste : <span class=\"kw-ttt\">nitrofurantoïne</span> <span class=\"kw-chiffre\">7 j</span> puis <span class=\"kw-ttt\">fosfomycine</span> dose unique</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-bio\">ECBU de contrôle</span> si persistance des symptômes après <span class=\"kw-chiffre\">3 j</span></li></ul>"},{"id":"q-pna-strat","kind":"decision","label":"Stratifier la PNA — Gravité d'abord, puis FR de complication","branches":[{"to":"t-pna-grave","label":"Sepsis, choc, qSOFA > 2 ou obstacle","color":"red"},{"to":"t-pna-risque","label":"FR de complication (dont grossesse)","color":"amber"},{"to":"t-pna-simple","label":"Aucun FR ni signe de gravité","color":"green"}]},{"id":"t-pna-grave","kind":"terminal","label":"PNA grave — Urgence — hospitalisation","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span> ; <span class=\"kw-alerte\">sepsis</span> / <span class=\"kw-alerte\">choc</span> → soins critiques</li><li><span class=\"kw-ttt\">Drainage en urgence</span> (<span class=\"kw-ttt\">sonde JJ</span> / <span class=\"kw-ttt\">néphrostomie</span>) si <span class=\"kw-radio\">dilatation des cavités pyélocalicielles</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">ECBU + hémocultures</span> ; <span class=\"kw-imagerie\">uroscanner</span> en <span class=\"kw-alerte\">urgence</span> <span class=\"kw-chiffre\">&lt; 24h</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">C3G parentérale + amikacine</span></li><li>Si FR d'<span class=\"kw-etio\">EBLSE</span> : <span class=\"kw-ttt\">carbapénème + amikacine</span></li></ul>"},{"id":"t-pna-risque","kind":"terminal","label":"PNA à risque de complication — Hospitalisation selon le terrain","color":"amber","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">ECBU</span> + <span class=\"kw-bio\">CRP, créatinine, urée</span></li><li><span class=\"kw-imagerie\">Uroscanner</span> en <span class=\"kw-alerte\">urgence</span> <span class=\"kw-chiffre\">&lt; 24h</span> (<span class=\"kw-imagerie\">échographie</span> si CI)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">FQ per os</span> ou <span class=\"kw-ttt\">C3G parentérale</span> (si hospit) ; adaptée <span class=\"kw-ttt\">amoxicilline</span> <span class=\"kw-chiffre\">10 j</span></li><li>La <span class=\"kw-etio\">grossesse</span> est un FR de complication (PNA gravidique)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Réévaluation</span> clinique à <span class=\"kw-chiffre\">72h</span></li></ul>"},{"id":"t-pna-simple","kind":"terminal","label":"PNA simple — Ambulatoire le plus souvent","color":"green","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">BU, ECBU</span> ; pas de biologie</li><li><span class=\"kw-imagerie\">Échographie</span> non systématique (si hyperalgique <span class=\"kw-chiffre\">&lt; 24h</span> ou échec à<span class=\"kw-chiffre\"> 72h</span>)</li></ul><h4>Traitement</h4><ul><li>Probabiliste : <span class=\"kw-ttt\">FQ per os</span> (ou <span class=\"kw-ttt\">C3G parentérale</span> si quinolone <span class=\"kw-chiffre\">&lt; 6 mois</span>)</li><li>Adaptée : <span class=\"kw-ttt\">amoxicilline</span> <span class=\"kw-chiffre\">10 j</span> ; voie orale privilégiée</li></ul><h4>Conduite</h4><ul><li>Ambulatoire ; <span class=\"kw-clinique\">réévaluation à 72h</span></li></ul>"}]},"cards":[{"i":"12a317aa71b4","n":161,"o":"161-14","u":"Prise en charge","t":"Connaître les modalités du traitement des infections urinaires masculines et connaître les modalités de leur prévention","q":"Quelles sont les modalités de prévention des infections urinaires lors de gestes urologiques, notamment les biopsies prostatiques ?","a":"<p>Pour prévenir les infections urinaires lors de gestes urologiques, comme les biopsies prostatiques ou les gestes endo-urétraux, une <strong>antibioprophylaxie par Fluoroquinolone</strong> doit être administrée <strong>1 à 2 heures avant</strong> le geste.</p>"},{"i":"5707d1515d1a","n":161,"o":"161-14","u":"Prise en charge","t":"Connaître les modalités du traitement des infections urinaires masculines et connaître les modalités de leur prévention","q":"Quelle est la stratégie antibiotique de première intention pour le traitement probabiliste d'une infection urinaire masculine sévère (avec fièvre, RAU ou immunodépression) ?","a":"<p>En cas d'infection urinaire masculine sévère, le traitement probabiliste s'oriente vers une <strong>C3G IV</strong> ou une <strong>Fluoroquinolone</strong>. En cas de sepsis ou de choc septique, une <strong>C3G IV associée à l'amikacine</strong> est recommandée, avec une possible couverture des BLSE si le contexte l'évoque.</p>"},{"i":"621ecd6686bc","n":161,"o":"161-14","u":"Prise en charge","t":"Connaître les modalités du traitement des infections urinaires masculines et connaître les modalités de leur prévention","q":"Quelle est la stratégie antibiotique de première intention pour le traitement probabiliste d'une infection urinaire masculine symptomatique et peu sévère (sans fièvre, RAU, ni immunodépression) ?","a":"<p>Pour une infection urinaire masculine symptomatique peu sévère, le traitement probabiliste privilégie une <strong>Fluoroquinolone per os</strong> (ciprofloxacine, lévofloxacine) en raison de son excellente diffusion prostatique.</p>"},{"i":"6e3815254b15","n":161,"o":"161-14","u":"Prise en charge","t":"Connaître les modalités du traitement des infections urinaires masculines et connaître les modalités de leur prévention","q":"Quelles sont les contre-indications ou précautions concernant les AINS et les alpha-bloquants dans le contexte d'une infection urinaire masculine ?","a":"<p>Les <strong>AINS sont contre-indiqués</strong> dans le traitement d'une infection urinaire masculine. En revanche, un <strong>alpha-bloquant</strong> peut être envisagé pour soulager une dysurie associée.</p>"},{"i":"7aa4537a5d3c","n":161,"o":"161-14","u":"Prise en charge","t":"Connaître les modalités du traitement des infections urinaires masculines et connaître les modalités de leur prévention","q":"Quelle est la durée du traitement antibiotique d'une infection urinaire masculine ?","a":"<p>La durée du traitement antibiotique d'une infection urinaire masculine est d'au moins <strong>14 jours</strong>. Elle peut être prolongée à <strong>21 jours</strong> si un autre antibiotique qu'une fluoroquinolone est utilisé, ou en présence d'une lithiase, d'une immunodépression, ou d'un trouble urinaire sous-jacent.</p>"},{"i":"c0627f4d1feb","n":161,"o":"161-14","u":"Prise en charge","t":"Connaître les modalités du traitement des infections urinaires masculines et connaître les modalités de leur prévention","q":"Comment doit-on gérer une Rétention Aiguë d'Urines (RAU) associée à une infection urinaire masculine ?","a":"<p>En cas de Rétention Aiguë d'Urines (RAU) associée à une infection urinaire masculine, un <strong>drainage des voies urinaires</strong> est nécessaire. Le <strong>cathéter sus-pubien</strong> est préféré, car le sondage urétral est une contre-indication relative en présence de prostatite.</p>"},{"i":"0ae0629b6a1d","n":161,"o":"161-15","u":"Prise en charge","t":"Connaître les modalités du traitement des infections urinaires au cours de la grossesse et son suivi","q":"Quelles sont les modalités de suivi ECBU après le traitement d'une infection urinaire chez la femme enceinte ?","a":"<p>Après le traitement d'une infection urinaire chez la femme enceinte, un <strong>ECBU de contrôle</strong> doit être réalisé <strong>8 à 10 jours après la fin du traitement</strong>, puis un <strong>ECBU mensuel systématique</strong> jusqu'à l'accouchement.</p>"},{"i":"379196e34607","n":161,"o":"161-15","u":"Prise en charge","t":"Connaître les modalités du traitement des infections urinaires au cours de la grossesse et son suivi","q":"Comment traiter une cystite gravidique ?","a":"<p>Une cystite gravidique doit être traitée <strong>sans attendre l'antibiogramme</strong>, avec une adaptation secondaire si nécessaire. Un <strong>ECBU de contrôle</strong> est impératif après le traitement.</p>"},{"i":"7afa6db60d1e","n":161,"o":"161-15","u":"Prise en charge","t":"Connaître les modalités du traitement des infections urinaires au cours de la grossesse et son suivi","q":"Quelle est la particularité du traitement d'une colonisation urinaire gravidique ?","a":"<p>La colonisation urinaire gravidique est la <strong>seule colonisation bactérienne systématiquement traitée</strong> en raison des risques liés à la grossesse. Le traitement doit être débuté <strong>d'emblée selon l'antibiogramme</strong> (pas de probabiliste).</p>"},{"i":"8075ad061fe1","n":161,"o":"161-15","u":"Prise en charge","t":"Connaître les modalités du traitement des infections urinaires au cours de la grossesse et son suivi","q":"Comment dépiste-t-on une colonisation urinaire gravidique et quel est son seuil diagnostique ?","a":"<p>Le dépistage de la colonisation urinaire gravidique se fait par un <strong>ECBU mensuel systématique</strong> à partir du 4ème mois de grossesse (après une bandelette urinaire mensuelle auparavant). Le diagnostic est posé sur la présence d'une bactériurie ≥ <strong>10⁵ UFC/mL</strong> sur <strong>deux ECBU consécutifs</strong>.</p>"},{"i":"9f507a1c09c2","n":161,"o":"161-15","u":"Prise en charge","t":"Connaître les modalités du traitement des infections urinaires au cours de la grossesse et son suivi","q":"Quelle est la prise en charge initiale d'une pyélonéphrite aiguë gravidique ?","a":"<p>Une pyélonéphrite aiguë gravidique nécessite une <strong>hospitalisation</strong>, une antibiothérapie par <strong>C3G parentérale</strong> et une <strong>surveillance materno-fœtale</strong>.</p>"},{"i":"b21433715d45","n":161,"o":"161-15","u":"Prise en charge","t":"Connaître les modalités du traitement des infections urinaires au cours de la grossesse et son suivi","q":"Pourquoi une infection urinaire pendant la grossesse est-elle toujours considérée \"à risque\" ?","a":"<p>Toute infection urinaire chez la femme enceinte est considérée \"à risque\" en raison du risque de <strong>pyélonéphrite aiguë (PNA)</strong> maternelle et de <strong>prématurité</strong> fœtale.</p>"},{"i":"0ddbe126a817","n":161,"o":"161-16","u":"Prise en charge","t":"Connaître les spécificités de l'infection urinaire de la personne âgée","q":"Quelles sont les spécificités microbiologiques des infections urinaires chez la personne âgée ?","a":"<ul><li>La proportion d'<em>E. coli</em> est <strong>inférieure à 50 %</strong>.</li><li>Il y a une plus grande fréquence de <strong>bactéries Gram positifs</strong>.</li><li>On observe un <strong>fort taux de résistance</strong> en institution.</li></ul>"},{"i":"25fd4d68b653","n":161,"o":"161-16","u":"Prise en charge","t":"Connaître les spécificités de l'infection urinaire de la personne âgée","q":"Quelle est la particularité épidémiologique de l'infection urinaire chez la personne âgée ?","a":"<p>L'infection urinaire est la <strong>deuxième cause d'infection</strong> chez le sujet âgé.</p>"},{"i":"62831740e924","n":161,"o":"161-16","u":"Prise en charge","t":"Connaître les spécificités de l'infection urinaire de la personne âgée","q":"Quels sont les principaux facteurs de risque d'infection urinaire chez la personne âgée ?","a":"<ul><li><strong>Apports hydriques insuffisants</strong>.</li><li><strong>Pathologie prostatique</strong> chez l'homme.</li><li><strong>Ménopause</strong> chez la femme.</li><li><strong>Incontinence</strong>.</li><li><strong>Vessie neurologique</strong>.</li><li>Utilisation d'<strong>anticholinergiques</strong>.</li></ul>"},{"i":"830ce5170ec0","n":161,"o":"161-16","u":"Prise en charge","t":"Connaître les spécificités de l'infection urinaire de la personne âgée","q":"Quel est le piège majeur à éviter lors du diagnostic d'une infection urinaire chez une personne âgée fébrile ?","a":"<p>Devant une fièvre, une bactériurie associée à une leucocyturie <strong>SANS signe urinaire</strong> ne permet PAS de rattacher la fièvre à une infection urinaire. La bactériurie et la leucocyturie sont fréquentes sans infection chez la personne âgée (colonisation). Seule la <strong>modification récente des signes urinaires doit alerter</strong>.</p>"},{"i":"d99e73c346c0","n":161,"o":"161-16","u":"Prise en charge","t":"Connaître les spécificités de l'infection urinaire de la personne âgée","q":"Quelles sont les adaptations thérapeutiques spécifiques à l'infection urinaire de la personne âgée ?","a":"<ul><li>Il ne faut pas utiliser de <strong>traitements courts</strong>.</li><li>Il est nécessaire d'<strong>adapter la posologie</strong> des antibiotiques à la <strong>clairance de la créatinine</strong> (calculée selon Cockcroft ou MDRD).</li></ul>"},{"i":"dc5e9d86b903","n":161,"o":"161-16","u":"Prise en charge","t":"Connaître les spécificités de l'infection urinaire de la personne âgée","q":"Quelles sont les particularités diagnostiques des infections urinaires chez la personne âgée ?","a":"<ul><li>La <strong>fièvre est absente dans 30 %</strong> des cas ou peut être une <strong>fièvre nue</strong>.</li><li>Les <strong>douleurs abdominales</strong> sont plus fréquentes que les douleurs lombaires (20 %).</li><li>La présentation peut être trompeuse, incluant : <strong>confusion</strong>, <strong>chutes</strong>, <strong>altération de l'état général (AEG)</strong>, <strong>syndrome de glissement</strong> ou <strong>décompensation d'une comorbidité</strong>.</li></ul>"},{"i":"2be2eef3423f","n":161,"o":"161-17","u":"Diagnostic positif","t":"Savoir évoquer une infection urinaire de l'enfant : enquête clinique","q":"Quand faut-il évoquer une infection urinaire chez l'enfant, en particulier avant l'âge de 3 mois ?","a":"<p>Il faut toujours évoquer une infection urinaire chez l'enfant s'il présente une <strong>fièvre sans point d'appel</strong> avant l'âge de <strong>3 mois</strong>.</p>"},{"i":"b384c5faeda2","n":161,"o":"161-17","u":"Diagnostic positif","t":"Savoir évoquer une infection urinaire de l'enfant : enquête clinique","q":"Quels sont les éléments cliniques faisant suspecter une infection urinaire chez l'enfant au-delà de 3 mois ?","a":"<p>Au-delà de 3 mois, une infection urinaire doit être suspectée devant :</p><ul><li>Une <strong>fièvre isolée persistante</strong> &gt; 48 heures.</li><li>Des <strong>signes fonctionnels urinaires</strong>.</li><li>Des <strong>antécédents de pyélonéphrite aiguë (PNA)</strong> ou de malformation des voies urinaires.</li></ul>"},{"i":"c836723ee24b","n":161,"o":"161-17","u":"Diagnostic positif","t":"Savoir évoquer une infection urinaire de l'enfant : enquête clinique","q":"Quelles sont les particularités cliniques de la pyélonéphrite aiguë (PNA) et de la cystite aiguë chez l'enfant ?","a":"<p>Les particularités cliniques sont :</p><ul><li><strong>Pyélonéphrite aiguë (PNA)</strong> : <ul><li>Fièvre / signes généraux <strong>+++</strong>.</li><li>Signes fonctionnels urinaires <strong>+</strong>.</li><li>Douleur <strong>lombo-abdominale</strong>, palpation lombaire douloureuse (inconstant).</li><li>Chez le <strong>nouveau-né</strong> : troubles digestifs, ictère, déshydratation.</li><li>Chez le <strong>nourrisson</strong> : fièvre inexpliquée + troubles hémodynamiques.</li><li>Chez le <strong>grand enfant</strong> : tableau adulte.</li></ul></li><li><strong>Cystite aiguë</strong> : <ul><li>Fièvre / signes généraux <strong>0</strong>.</li><li>Signes fonctionnels urinaires <strong>+++</strong>.</li><li>Douleur <strong>hypogastrique</strong>.</li><li>Elle touche surtout la <strong>fille</strong>, avec des signes fonctionnels urinaires intenses.</li></ul></li></ul>"},{"i":"d05d82438cbc","n":161,"o":"161-17","u":"Diagnostic positif","t":"Savoir évoquer une infection urinaire de l'enfant : enquête clinique","q":"Quelle est la prévalence de l'infection urinaire chez l'enfant fébrile et quelle est sa gravité avant 1 an ?","a":"<p>L'infection urinaire est très fréquente chez l'enfant, touchant <strong>7,5 % des fièvres avant 2 ans</strong>. Avant l'âge de 1 an, il s'agit d'une <strong>pyélonéphrite aiguë (PNA) dans 95 % des cas</strong>.</p>"},{"i":"18beddd5be8e","n":161,"o":"161-18","u":"Examens complémentaires","t":"Connaître les modalités de prescription du ou des examens complémentaires chez l'enfant","q":"Quelle est l'importance de l'examen des urines pour le diagnostic d'infection urinaire chez l'enfant et quel facteur clé conditionne son interprétation ?","a":"<p>Le diagnostic d'infection urinaire chez l'enfant ne peut être affirmé que par l'<strong>examen des urines</strong>. La <strong>qualité du prélèvement</strong> conditionne son interprétation.</p>"},{"i":"30e7bec4fbdd","n":161,"o":"161-18","u":"Examens complémentaires","t":"Connaître les modalités de prescription du ou des examens complémentaires chez l'enfant","q":"Quel est le seul examen d'imagerie de première intention à réaliser en cas d'infection urinaire chez l'enfant, et dans quelle situation est-il systématique ?","a":"<p>Le seul examen d'imagerie de première intention est l'<strong>échographie réno-vésicale</strong>. Elle est <strong>systématique au premier épisode de pyélonéphrite aiguë (PNA)</strong>. La scintigraphie et l'uro-TDM/IRM ne sont pas réalisées en routine.</p>"},{"i":"7df00f9b114b","n":161,"o":"161-18","u":"Examens complémentaires","t":"Connaître les modalités de prescription du ou des examens complémentaires chez l'enfant","q":"Quand faut-il réaliser une bandelette urinaire (BU) et un ECBU chez l'enfant en fonction de l'âge ?","a":"<ul><li>Pour les enfants <strong>> 1 mois</strong> : une <strong>BU est réalisée en premier</strong>. Si elle est positive, un ECBU est nécessaire. Si la BU est négative (VPN <strong>97 %</strong>), il n'y a pas besoin d'ECBU.</li><li>Pour les enfants <strong>< 1 mois</strong> : un <strong>ECBU d'emblée</strong> est systématique car la BU est peu sensible à cet âge.</li></ul>"},{"i":"b820ca0d2ac8","n":161,"o":"161-18","u":"Examens complémentaires","t":"Connaître les modalités de prescription du ou des examens complémentaires chez l'enfant","q":"Quels sont les différents modes de recueil des urines pour un ECBU chez l'enfant, et leurs principales caractéristiques (avantages, inconvénients, pièges) ?","a":"<ul><li>Le <strong>collecteur adhésif</strong> : le plus utilisé mais avec une VPP médiocre (jusqu'à <strong>50 % de faux positifs</strong>), utile seulement s'il est négatif, pose ≤ <strong>30 min</strong>.</li><li>Le <strong>milieu de jet</strong> : à privilégier (non invasif), VPP meilleure (~ <strong>20 % de faux positifs</strong>).</li><li>Le <strong>cathétérisme urétral</strong> : alternative avant <strong>2 ans</strong>, évite la contamination (<strong>10 % de faux positifs</strong>).</li><li>La <strong>ponction sus-pubienne</strong> : échoguidée, indications limitées.</li></ul>"},{"i":"b8799f3341b5","n":161,"o":"161-18","u":"Examens complémentaires","t":"Connaître les modalités de prescription du ou des examens complémentaires chez l'enfant","q":"Quels sont les seuils de bactériurie à prendre en compte pour affirmer le diagnostic d'infection urinaire en fonction du mode de recueil chez l'enfant ?","a":"<ul><li><strong>10⁴ UFC/mL</strong> (pour le collecteur adhésif).</li><li><strong>10³ UFC/mL</strong> (pour le jet/cathéter).</li><li><strong>10² UFC/mL</strong> (pour la ponction sus-pubienne).</li></ul>"},{"i":"cb59fa9b4706","n":161,"o":"161-18","u":"Examens complémentaires","t":"Connaître les modalités de prescription du ou des examens complémentaires chez l'enfant","q":"Dans quels cas doit-on réaliser des hémocultures et une ponction lombaire (PL) chez l'enfant présentant une pyélonéphrite aiguë (PNA) ?","a":"<ul><li>Les <strong>hémocultures</strong> doivent être réalisées en cas de PNA chez un enfant <strong>< 3 mois</strong> ou en présence de <strong>critères de gravité</strong>.</li><li>Une <strong>ponction lombaire</strong> doit être réalisée en cas de PNA chez un enfant <strong>< 6 semaines</strong>, en raison du risque de méningite.</li></ul>"},{"i":"023ad5a73851","n":161,"o":"161-9","u":"Diagnostic positif","t":"Connaître les critères diagnostiques des pyélonéphrites aiguës (cliniques, biologiques, radiologiques) avec ou sans signe de gravité (algorithme)","q":"Comment évalue-t-on le caractère de gravité ou de risque de complication d'une pyélonéphrite aiguë ?","a":"<ul><li><strong>Gravité</strong> : Une PNA est considérée comme grave en présence de critères de <strong>sepsis</strong>, de <strong>choc</strong>, ou si elle survient après un <strong>geste urologique</strong>, correspondant à un score qSOFA ≥ 2.</li><li><strong>Facteurs de risque de complication</strong> : Leur présence définit une PNA à risque, sinon il s'agit d'une PNA simple.</li></ul>"},{"i":"0fb458bc3fa5","n":161,"o":"161-9","u":"Diagnostic positif","t":"Connaître les critères diagnostiques des pyélonéphrites aiguës (cliniques, biologiques, radiologiques) avec ou sans signe de gravité (algorithme)","q":"Quelle est la définition clinique d'une pyélonéphrite aiguë (PNA) ?","a":"<p>La pyélonéphrite aiguë se définit comme une inflammation du rein et de sa voie excrétrice, se manifestant cliniquement par l'association d'un <strong>syndrome infectieux</strong> et de <strong>douleurs lombaires</strong> unilatérales.</p>"},{"i":"b459da45ef90","n":161,"o":"161-9","u":"Diagnostic positif","t":"Connaître les critères diagnostiques des pyélonéphrites aiguës (cliniques, biologiques, radiologiques) avec ou sans signe de gravité (algorithme)","q":"Quels sont les principaux signes cliniques d'une pyélonéphrite aiguë ?","a":"<ul><li>Un <strong>syndrome infectieux</strong> systématique, incluant <strong>fièvre</strong> et <strong>frissons</strong>.</li><li>Des prodromes de cystite peuvent être présents mais sont inconstants (50% des cas).</li><li>Une <strong>douleur lombaire unilatérale</strong>, exacerbée par la percussion de la fosse lombaire, avec irradiation vers les organes génitaux externes (OGE).</li><li>Des <strong>signes digestifs</strong> par iléus réflexe (vomissements, diarrhée, météorisme) qui peuvent parfois être au premier plan.</li></ul>"},{"i":"d9a68aeacc49","n":161,"o":"161-9","u":"Diagnostic positif","t":"Connaître les critères diagnostiques des pyélonéphrites aiguës (cliniques, biologiques, radiologiques) avec ou sans signe de gravité (algorithme)","q":"Quand et quel type d'imagerie est indiqué dans le diagnostic d'une pyélonéphrite aiguë ?","a":"<ul><li>Une <strong>échographie</strong> est indiquée en urgence (moins de 24 heures) si la douleur est <strong>hyperalgique</strong>.</li><li>Un <strong>uroscanner</strong> est à réaliser dans les 24 heures si la PNA est à <strong>risque de complication</strong> ou <strong>grave</strong>, afin de rechercher un <strong>obstacle</strong> ou un <strong>foyer de néphrite</strong>.</li></ul>"},{"i":"fb7ec303842b","n":161,"o":"161-9","u":"Diagnostic positif","t":"Connaître les critères diagnostiques des pyélonéphrites aiguës (cliniques, biologiques, radiologiques) avec ou sans signe de gravité (algorithme)","q":"Quels examens biologiques initiaux sont indiqués devant une suspicion de pyélonéphrite aiguë ?","a":"<ul><li>Une <strong>bandelette urinaire (BU)</strong> et un <strong>examen cytobactériologique des urines (ECBU)</strong> sont systématiques.</li><li>La <strong>CRP</strong>, la <strong>créatinine</strong> et l'<strong>urée</strong> sont recommandées si la pyélonéphrite aiguë est considérée à risque.</li><li>Des <strong>hémocultures</strong> sont à réaliser si la PNA est grave (elles sont positives dans 25% des cas).</li></ul>"}]};